choose.when:
AND (
  status = 'expired'
  OR (
    expires_at IS NOT NULL
    AND expires_at <= #{now}
    AND status NOT IN ('connected', 'rejected', 'revoked')
  )
)

choose.otherwise:
AND status = #{status}
AND NOT (
  expires_at IS NOT NULL
  AND expires_at <= #{now}
  AND status NOT IN ('connected', 'rejected', 'revoked', 'expired')
)

mapper.select:
SELECT *
FROM wechat_bind_links

ORDER BY created_at DESC, token ASC
LIMIT #{pageSize}
OFFSET #{offset}

mapper.delete:
DELETE FROM wechat_bind_links
WHERE phone = #{phone}
   OR target_account_id = #{accountId}
